def compute(vars):
    old_index = vars["v1"]
    new_index = vars["v2"]
    if old_index == 0:
        return None

    change_ratio = (new_index - old_index) / old_index
    investment = 100000
    total_return = investment * change_ratio

    return {
        "value": total_return,
        "trace": {
            "change_ratio": change_ratio,
            "investment": investment,
            "output_meta": {
                "currency": "USD",
                "scale": "ones",
                "unit": "currency",
            },
        },
    }
